    task_cfg: dict[str, Any],

class VerifierEngine:
    """Runs database_state, response_check, tool_execution, json_match and
    rubric_check verifiers. Multi-gym aware."""

    def __init__(
        self,
        protocol_clients: Dict,
        llm_client: LLMClient,
        execution_mode: str = "openenv",
        judge_llm_client: Optional[LLMClient] = None,
        judge_vote_count: int = 1,
    ):
        self.protocol_clients = protocol_clients
        self.llm_client = llm_client
        self.execution_mode = execution_mode
        # Dedicated LLM-as-judge for rubric_check / response_check grading. A
        # fixed strong model grades verdicts so they never depend on (or are
        # graded by) the candidate model under test. Falls back to the
        # candidate client (self-grading) when no independent judge is wired in,
        # so existing callers and tests keep working unchanged.
        self.judge_llm_client = judge_llm_client or llm_client
        self.judge_vote_count = max(1, int(judge_vote_count))

    async def _collect_judge_responses(
        self, messages: List[Any], *, response_usable
    ) -> tuple[List[str], List[str]]:
        """Collect independent judge samples without letting one outage abort all votes."""

        async def invoke_one() -> str:
            return await self._invoke_judge_llm(
                messages, response_usable=response_usable
            )

        raw_results = await asyncio.gather(
            *(invoke_one() for _ in range(self.judge_vote_count)),
            return_exceptions=True,
        )
        usable: List[str] = []
        errors: List[str] = []
        for result in raw_results:
            if isinstance(result, BaseException):
                errors.append(str(result))
            elif response_usable(result):
                usable.append(result)
            else:
                errors.append("empty or invalid response schema")
        return usable, errors

    async def _judge_ainvoke(self, messages: List[Any]) -> Any:
        """Invoke the judge via LLMClient.ainvoke when available (provider retry)."""
        client = self.judge_llm_client
        ainvoke = getattr(client, "ainvoke", None)
        if callable(ainvoke):
            return await ainvoke(messages)
        return await client.llm.ainvoke(messages)

    async def _invoke_judge_llm(
        self,
        messages: List[Any],
        *,
        response_usable,
    ) -> str:
        """Call the judge LLM, retrying on empty or unparseable JSON replies.

        Provider transport/rate-limit retries (#104) run inside
        ``judge_llm_client.ainvoke``; this outer loop only handles content
        flakes (empty body or JSON that fails to parse).
        """
        max_attempts = max(1, _env_int("TH_JUDGE_JSON_RETRY_MAX", 3))
        delay = 0.5
        last_text = ""
        for attempt in range(1, max_attempts + 1):
            response = await self._judge_ainvoke(messages)
            last_text = _normalize_ai_content(response)
            if response_usable(last_text):
                return last_text
            if attempt < max_attempts:
                logger.warning(
                    "Judge returned empty/unparseable JSON (attempt %d/%d); "
                    "retrying in %.1fs",
                    attempt,
                    max_attempts,
                    delay,
                )
                await asyncio.sleep(delay)
                delay = min(delay * 2, 4.0)
        return last_text

    def _get_protocol_client_for_gym(self, gym_name: Optional[str] = None):
        """Get the correct protocol client for a specific gym"""
        if not gym_name:

            return list(self.protocol_clients.values())[0]

        if gym_name in self.protocol_clients:
            return self.protocol_clients[gym_name]

        return list(self.protocol_clients.values())[0]

    async def execute_verifier(
        self,
        verifier: VerifierConfig,
        model_response: Dict[str, Any],
        gym_name: Optional[str] = None,
    ) -> Dict[str, Any]:
        """Execute a single verifier"""
        logger.info(f"Executing verifier: {verifier.verifier_type}")

        if verifier.verifier_type == "database_state":
            return await self._execute_database_state_verifier(
                verifier.validation_config, gym_name
            )
        elif verifier.verifier_type == "response_check":
            return await self._execute_response_check_verifier(
                verifier.validation_config,
                model_response,
                gym_name,
            )
        elif verifier.verifier_type == "tool_execution":
            return await self._execute_tool_execution_verifier(
                verifier.validation_config, model_response
            )
        elif verifier.verifier_type == "json_match":
            return self._execute_json_match_verifier(
                verifier.validation_config, model_response
            )
        elif verifier.verifier_type == "source_json_match":
            return await self._execute_source_json_match_verifier(
                verifier.validation_config, model_response
            )
        elif verifier.verifier_type == "rubric_check":
            return await self._execute_rubric_check_verifier(
                verifier.validation_config, model_response, gym_name
            )
        elif verifier.verifier_type == "file_check":
            return await self._execute_file_check_verifier(
                verifier.validation_config, model_response, gym_name
            )
        elif verifier.verifier_type == "gym_state_check":
            return await self._execute_gym_state_check_verifier(
                verifier.validation_config, gym_name
            )
        else:
            return {
                "passed": False,
                "error": f"Unsupported verifier type: {verifier.verifier_type}",
            }

    async def _execute_file_check_verifier(
        self,
        validation_config: Dict[str, Any],
        model_response: Dict[str, Any],
        gym_name: Optional[str] = None,
    ) -> Dict[str, Any]:
        """Grade the files the model produced in its per-run skills workspace.

        The skills flow runs the model's `bash` tool inside a fresh per-run
        workspace and records its path as `model_response["workspace_dir"]`.
        This verifier points rl-world-verifiers straight at that directory and
        evaluates an embedded spec (deterministic file-content checks and/or
        LLM rubrics). The scalar reward (0..1) maps to pass/fail via
        `pass_threshold` (default 1.0), so it flows through the existing
        core/secondary scoring path like any other verifier.
        """
        spec = validation_config.get("verifier_spec")
        if not spec:
            return {"passed": False, "error": "file_check: missing 'verifier_spec'"}

        offending = _spec_paths_under_input(spec)
        if offending:
            return {
                "passed": False,
                "error": (
                    "file_check: verifier spec reads seeded input files "
                    f"({', '.join(offending)}). A verifier must grade what the model "
                    f"produced, not the fixtures it was given. Point these at the "
                    f"deliverable paths instead."
                ),
            }

        threshold = float(validation_config.get("pass_threshold", 1.0))
        # Clamp to (0, 1]: a reward of 0.0 (no file produced, or every check failed)
        # must never satisfy the pass test, so pass_threshold <= 0 is not allowed to
        # grant a pass, and a threshold above 1.0 is capped so a perfect run passes.
        threshold = min(max(threshold, 1e-9), 1.0)

        workspace_dir = (model_response or {}).get("workspace_dir")
        if not workspace_dir or not os.path.isdir(workspace_dir):
            return {
                "passed": False,
                "error": "file_check: no workspace to grade. A file_check verifier "
                "auto-enables skills, so this only happens if TH_ENABLE_SKILLS was "
                "forced off (=0). Unset it (or set 1) so the bash tool writes a per-run "
                "workspace.",
                "gym_name": gym_name,
            }

        try:
            from rl_world_verifiers import run_verifier
        except Exception as exc:  # pragma: no cover - dependency/setup issue
            return {
                "passed": False,
                "error": f"file_check: rl_world_verifiers import failed ({exc}). "
                "Install the skills dependencies with `pip install -r requirements.txt` "
                "and run under Python >= 3.10 "
                "(see README.md, 'Document skills + file_check verifier').",
            }

        seeded_paths = (model_response or {}).get("seeded_input_paths") or []
        produced = list_workspace_files(workspace_dir, seeded_paths)
        produced_names = [f.get("path") if isinstance(f, dict) else f for f in produced]

        out_dir = tempfile.mkdtemp(prefix="filecheck_out_")
        try:
            spec_path = os.path.join(out_dir, "verifier.json")
            with open(spec_path, "w", encoding="utf-8") as fh:
                json.dump(spec, fh)

            # run_verifier is synchronous; keep the event loop free.
            payload = await asyncio.to_thread(
                run_verifier,
                spec_path=Path(spec_path),
                workspace_dir=Path(workspace_dir),
                verifier_dir=Path(out_dir),
            )
            reward = float(payload.get("reward", 0.0))
            summary = payload.get("summary", {})
            return {
                "passed": reward >= threshold,
                "reward": reward,
                "threshold": threshold,
                "workspace_files": produced_names,
                "summary": summary,
                "assertion_results": payload.get("assertion_results"),
                "gym_name": gym_name,
            }
        except Exception as exc:
            return {
                "passed": False,
                "error": f"file_check: verifier run failed: {exc}",
                "workspace_files": produced_names,
                "gym_name": gym_name,
            }
        finally:
            shutil.rmtree(out_dir, ignore_errors=True)

    async def _execute_database_state_verifier(
        self,
        validation_config: Dict[str, Any],
        gym_name: Optional[str] = None,
    ) -> Dict[str, Any]:
        """Execute database state verifier"""
        sql_query = validation_config.get("sql_query")
        expected_value = validation_config.get("expected_value")
        comparison_type = validation_config.get("comparison_type", "equals")

        if not sql_query:
            return {"passed": False, "error": "No SQL query provided"}

        logger.info(f"Executing SQL query: {sql_query}")
        if gym_name:
            logger.info(f"  Target gym: {gym_name}")

        result = await self._execute_sql_query(sql_query, gym_name)

        if not result["success"]:
            return {
                "passed": False,
                "error": f"SQL query failed: {result.get('error')}",
                "query": sql_query,
            }

        actual_value = self._extract_value_from_sql_result(result)

        logger.info(f"SQL result - Expected: {expected_value}, Actual: {actual_value}")

        comparison_result = self._compare_values(
            actual_value, expected_value, comparison_type
        )

        return {
            "passed": comparison_result["passed"],
            "expected": expected_value,
            "actual": actual_value,
            "comparison_type": comparison_type,
            "query": sql_query,
            "gym_name": gym_name,
            "details": comparison_result.get("details"),
        }

    def _execute_json_match_verifier(
        self,
        validation_config: Dict[str, Any],
        model_response: Dict[str, Any],
    ) -> Dict[str, Any]:
        """Compare parsed JSON in the model response to expected values."""
        expected = validation_config.get("expected") or {}
        if not expected:
            return {

    def __init__(self, judge_cfg):
        self.llm = _LitellmJudge(judge_cfg)


# ---------------------------------------------------------------------------
# Trace evidence for ``rubric_check`` (target="trace")
# ---------------------------------------------------------------------------
# Trace rubrics used to get ``{name, args}`` only — the judge saw the call but
# never its result, so any rubric about a *finding* was ungradeable. Results are
# included now, clipped per call so one schema dump can't eat the whole budget.
_TRACE_RESULT_MAX_CHARS = int(os.environ.get("RUBRIC_TRACE_RESULT_CHARS", "4000"))
_TRACE_RESULT_MIN_CHARS = int(os.environ.get("RUBRIC_TRACE_RESULT_MIN_CHARS", "200"))
_TRACE_EVIDENCE_MAX_CHARS = int(os.environ.get("RUBRIC_TRACE_EVIDENCE_CHARS", "200000"))


def _clip_json_value(value: Any, limit: int) -> str:
    """Compact-serialize *value* and clip it to *limit* chars, flagging the cut."""
    try:
        text = json.dumps(value, separators=(",", ":"), default=str)
    except (TypeError, ValueError):
        text = str(value)
    if len(text) <= limit:
        return text
    # Head+tail: results lead with schema boilerplate and carry the rows at the
    # end (``data_array``), so a head-only clip drops every value.
    head = limit // 3
    tail = limit - head
    return (
        text[:head]
        + f"… [{len(text) - limit} chars clipped] …"
        + text[-tail:]
    )


def _build_trace_evidence(
    tool_calls: List[Any],
    include_outcomes: bool = False,
) -> str:
    """Trace evidence: each call with its result, clipped to cap/n_calls."""
    calls = [tc for tc in tool_calls if isinstance(tc, dict)]
    per_call = _TRACE_EVIDENCE_MAX_CHARS // max(1, len(calls))
    per_call = max(_TRACE_RESULT_MIN_CHARS, min(_TRACE_RESULT_MAX_CHARS, per_call))
    entries: List[Dict[str, Any]] = []
    for tc in calls:
        entry: Dict[str, Any] = {
            "name": tc.get("name"),
            "args": tc.get("args") or tc.get("arguments"),
        }
        if include_outcomes:
            entry["accepted_by_gym"] = bool(tc.get("ok", True))
        result = tc.get("tool_execution_results")
        if result not in (None, {}, ""):
            entry["result"] = _clip_json_value(result, per_call)
        entries.append(entry)
    return json.dumps(entries, indent=2)


@dataclass
class VerifierConfig:
    """Configuration for a verifier.

    Every verifier gates pass/fail (single-tier; harness #555). ``category`` is
    retained as authoring metadata for existing task files and reports; it does
    not change grading. ``weight`` feeds the soft/weighted score (default 1.0).
    """

    verifier_type: str
    validation_config: Dict[str, Any]
    name: Optional[str] = None
    description: Optional[str] = None
    gym_name: Optional[str] = None
    category: str = "core"
    weight: float = 1.0


def _extract_fenced_json_text(response_text: str) -> str:
    """Pull JSON body from a judge reply (handles ```json fences)."""
    text = (response_text or "").strip()
    if "```json" in text:
        return text.split("```json", 1)[1].split("```", 1)[0].strip()
    if "```" in text:
        return text.split("```", 1)[1].split("```", 1)[0].strip()
    return text


def _judge_json_parseable(response_text: str) -> bool:
    """True when the judge returned non-empty, JSON-parseable content."""
    text = (response_text or "").strip()
    if not text:
        return False
    try:
        json.loads(_extract_fenced_json_text(text))
        return True
    except Exception:
        return False


def _judge_rubric_response_usable(response_text: str) -> bool:
    """Validate the complete rubric-judge response contract (#555)."""
    try:
        value = json.loads(_extract_fenced_json_text(response_text))
    except Exception:
        return False
    return (
        isinstance(value, dict)
        and set(value) == {"verdict", "motivation"}
        and value.get("verdict") in ("PASS", "FAIL")
        and isinstance(value.get("motivation"), str)
        and bool(value["motivation"].strip())
    )


def _judge_score_response_usable(response_text: str) -> bool:
    """Validate the complete response-check judge contract (#555)."""
    try:
        value = json.loads(_extract_fenced_json_text(response_text))
    except Exception:
        return False
    score = value.get("score") if isinstance(value, dict) else None

import math
import re
from typing import Any

from jsonpath_ng.ext import parse as jsonpath_parse

from .models import Tolerance


def extract_jsonpath_values(data: Any, path: str) -> list[Any]:
    """Extracts all values matching a JSONPath expression.

    Args:
        data: JSON-like data to inspect.
        path: JSONPath expression to evaluate.

    Returns:
        List of matched values. The root path ``$`` returns the full input as a
        single matched value.
    """
    if path == "$":
        return [data]
    return [match.value for match in jsonpath_parse(path).find(data)]


def actual_from_matches(matches: list[Any]) -> Any:
    """Converts JSONPath matches into the result actual value.

    Args:
        matches: JSONPath matched values.

    Returns:
        ``None`` for no matches, the single value for one match, or the full
        match list for multiple matches.

    Note:
        The single-vs-list result depends on the match count, which changes
        comparison semantics: ``equals X`` compares the whole list when a path
        matches multiple nodes, while ``contains X`` then means "X is one of the
        matched nodes". Anchor JSONPaths that must be singular (e.g. ``[0]``) so a
        comparison is not silently evaluated against a list.
    """
    if not matches:
        return None
    if len(matches) == 1:
        return matches[0]
    return matches


def compare(
    *,
    actual: Any,
    expected: Any,
    comparison: str,
    tolerance: Tolerance | None = None,
) -> bool:
    """Compares an actual value against an expected value.

    Args:
        actual: Value produced by a source command and optional JSONPath.
        expected: Expected value from the verifier assertion.
        comparison: Comparator name from the verifier schema.
        tolerance: Optional absolute/relative tolerance.

    Returns:
        True when the comparison succeeds; otherwise false.

    Raises:
        TypeError: If values have unsupported types for the comparator.
        ValueError: If the comparator name is unsupported.
    """
    if comparison == "equals":
        return values_equal(actual, expected)
    if comparison == "not_equals":
        return not values_equal(actual, expected)
    if comparison == "approx_equals":
        assert_number_pair(actual, expected, comparison)
        return math.isclose(
            actual,
            expected,
            abs_tol=1e-9 if tolerance is None or tolerance.absolute is None else tolerance.absolute,
            rel_tol=1e-9 if tolerance is None or tolerance.relative is None else tolerance.relative,
        )
    if comparison == "contains":
        return contains(actual, expected)
    if comparison == "not_contains":
        return not contains(actual, expected)
    if comparison == "regex_match":
        assert_string(actual, comparison)
        return bool(re.search(str(expected), actual))
    if comparison == "not_regex_match":
        assert_string(actual, comparison)
        return not bool(re.search(str(expected), actual))
    if comparison == "in_array":
        assert_list(expected, comparison)
        return any(values_equal(actual, item) for item in expected)
    if comparison == "not_in_array":
        assert_list(expected, comparison)
        return not any(values_equal(actual, item) for item in expected)
    if comparison == "greater_than":
        assert_number_pair(actual, expected, comparison)
        return bool(actual > expected)
    if comparison == "less_than":
        assert_number_pair(actual, expected, comparison)
        return bool(actual < expected)
    if comparison == "greater_than_equal":
        assert_number_pair(actual, expected, comparison)
        return bool(actual >= expected)
    if comparison == "less_than_equal":
        assert_number_pair(actual, expected, comparison)
        return bool(actual <= expected)
    raise ValueError(f"unsupported comparison: {comparison}")


def contains(actual: Any, expected: Any) -> bool:
    """Checks string substring or list element containment.

    Args:
        actual: Container value.
        expected: Expected contained value.

    Returns:
        True when ``actual`` contains ``expected``.

    Raises:
        TypeError: If ``actual`` is not a string or list.
    """
    if isinstance(actual, str):
        if not isinstance(expected, str):
            raise TypeError(
                f"contains on a string requires string expected: expected_type={type(expected).__name__}"
            )
        return expected in actual
    if isinstance(actual, list):
        return any(values_equal(expected, item) for item in actual)
    raise TypeError(f"contains requires string or list actual: actual_type={type(actual).__name__}")


def assert_number_pair(actual: Any, expected: Any, comparison: str) -> None:
    """Requires both actual and expected values to be JSON numbers.

    Args:
        actual: Actual value.
        expected: Expected value.
        comparison: Comparator name for error messages.

    Raises:
        TypeError: If either value is not a number.
    """
    if not is_json_number(actual) or not is_json_number(expected):
        raise TypeError(
            f"{comparison} requires JSON numbers: "
            f"actual_type={type(actual).__name__} expected_type={type(expected).__name__}"
        )


def is_json_number(value: Any) -> bool:
    """Checks whether a value is a JSON number in Python form.

    Args:
        value: Value to inspect.

    Returns:
        True for int/float values except booleans.
    """
    return isinstance(value, (int, float)) and not isinstance(value, bool)


def values_equal(a: Any, b: Any) -> bool:
    """Equality that does NOT treat booleans as their integer values.

    Python evaluates ``True == 1`` and ``False == 0`` as true, which would let a
    document value of ``1`` satisfy ``equals: true`` (and vice versa). This treats
    booleans and numbers as distinct types, so a bool only matches a bool.

    Args:
        a: First value.
        b: Second value.

    Returns:
        True when the values are equal under bool-aware typing.
    """
    if isinstance(a, bool) != isinstance(b, bool):
        return False
    return bool(a == b)


def assert_string(actual: Any, comparison: str) -> None:
    """Requires actual to be a string.

    Args:
        actual: Actual value.
        comparison: Comparator name for error messages.

    Raises:
        TypeError: If actual is not a string.
    """
    if not isinstance(actual, str):
        raise TypeError(f"{comparison} requires string actual: actual_type={type(actual).__name__}")


def assert_list(expected: Any, comparison: str) -> None:
    """Requires expected to be a list.

    Args:
        expected: Expected value.
        comparison: Comparator name for error messages.

    Raises:
        TypeError: If expected is not a list.
    """
    if not isinstance(expected, list):
        raise TypeError(f"{comparison} requires expected to be an array")

def _call_succeeded(ter: Any) -> bool:
    """Whether the gym accepted a call. Consumers read a per-call ``ok`` that
    nothing ever wrote, so every call read as accepted. Optimistic: only an
    explicit error signal marks a call failed."""
    if not isinstance(ter, dict):
        return True
    if ter.get("success") is False:
        return False
    result = ter.get("result")
    if isinstance(result, dict):
        if result.get("isError"):
            return False
        status = result.get("status_code")
        if isinstance(status, int) and status >= 400:
            return False
    return True


def load_agent_trace(path: Path) -> list[dict]:
    """Load an agent's trace into the flat call list the scorer expects.

    Supports two formats:
      * **ATIF-v1.x** — `{steps: [{tool_calls, observation: {results}}, ...]}`.
        Joins each tool_call with the matching observation result by
        `source_call_id` and reconstructs `tool_execution_results`.
      * **flat list** — `[{name, arguments, tool_execution_results}, ...]`
        (legacy / simple shape).

    Strips the `mcp__<server>__` prefix Claude Code prepends so the
    name comparison against golden_trajectory.json's bare tool name works.
    """
    if not path.exists():
        return []
    data = load_json(path)

    def _strip_mcp_prefix(name: str) -> str:
        if isinstance(name, str) and name.startswith("mcp__"):
            parts = name.split("__", 2)
            if len(parts) == 3:
                return parts[2]
        return name

    if isinstance(data, dict) and "steps" in data:
        calls = []
        for s in data["steps"]:
            # Index observation results by source_call_id for fast lookup.
            results = ((s.get("observation") or {}).get("results") or [])
            obs_by_id: dict[str, dict] = {}
            for r in results:
                if isinstance(r, dict) and r.get("source_call_id"):
                    obs_by_id[r["source_call_id"]] = r
            tcs = s.get("tool_calls") or []
            for idx, tc in enumerate(tcs):
                tcid = tc.get("tool_call_id")
                obs = obs_by_id.get(tcid)
                # ``source_call_id`` is optional in ATIF and most emitters omit
                # it, so keying only on it dropped every result. Fall back to
                # position when nothing in the step is keyed.
                if obs is None and not obs_by_id and len(results) == len(tcs):
                    obs = results[idx]
                obs = obs if isinstance(obs, dict) else {}
                # ATIF: observation.content is a string (often stringified JSON).
                content = obs.get("content")
                payload = content
                if isinstance(content, str):
                    try:
                        payload = json.loads(content)
                    except (ValueError, TypeError):
                        payload = content
                # Some authors stash status_code / is_error in step.extra.
                extra = (s.get("extra") or {})
                ter = tc.get("result") or {
                    "success": extra.get("success", True),
                    "result": {
                        "status_code": extra.get("status_code"),
                        "isError": extra.get("is_error", False),
                        "payload": payload,
                    },
                }
                calls.append({
                    "name": _strip_mcp_prefix(
                        tc.get("function_name") or tc.get("name") or ""
                    ),
                    "arguments": tc.get("arguments") or {},
                    "tool_execution_results": ter,
                    "ok": _call_succeeded(ter),
                })
        return calls
    if isinstance(data, list):
        for c in data:
            if isinstance(c, dict) and "name" in c:
                c["name"] = _strip_mcp_prefix(c["name"])
            # Same ``ok`` contract as the ATIF branch.
            if isinstance(c, dict) and "ok" not in c:
                c["ok"] = _call_succeeded(c.get("tool_execution_results"))
        return data
    return []


# ---------------------------------------------------------------------------
# Rubric (hierarchical LLM judge)
# ---------------------------------------------------------------------------

# Char budget for the assembled judge evidence block. The old 24k default only
# fit ~10-15 steps of an indented-JSON trajectory, so any longer run was
# truncated mid-trajectory and the judge scored "no visible evidence" for
# everything past the cutoff. Default is now 120k and, more importantly, the
# per-batch/global ``manifest.rubric.evidence.max_chars`` overrides it.
_EVIDENCE_TRUNCATE_CHARS = int(os.environ.get("RUBRIC_EVIDENCE_CHARS", "120000"))

# Keys that are pure noise for a rubric judge and safe to drop from the
# trajectory JSON handed to it. Dropping them (plus null/empty values, plus
# compact serialization) roughly halves the evidence size WITHOUT removing any
# decision-relevant signal: tool names, arguments, success/error and result
# payloads are all preserved. ``captures`` is an internal wizard mapping;
# ``resolved_arguments`` duplicates ``arguments``; ``executed_at`` is a
# per-call timestamp the rubric never grades.
_EVIDENCE_TRAJECTORY_DROP_KEYS = frozenset(
    {"captures", "resolved_arguments", "executed_at"}
)


def _slim_evidence_value(value: Any) -> Any:
    """Recursively drop safe-to-drop keys and null/empty leaves.

    Conservative on purpose — it only removes structural noise and empty
    values, never domain data (a tool's arguments or its result payload).
    """
    if isinstance(value, dict):
        out: dict[str, Any] = {}
        for k, v in value.items():
            if k in _EVIDENCE_TRAJECTORY_DROP_KEYS:
                continue
            sv = _slim_evidence_value(v)
            # Preserve ``False`` / ``0`` (meaningful, e.g. success=False), only
            # strip genuinely empty leaves.
            if sv is None or sv == [] or sv == {} or sv == "":
                continue
            out[k] = sv
        return out
    if isinstance(value, list):
        return [_slim_evidence_value(v) for v in value]
    return value


def _slim_trajectory_for_evidence(trajectory: Any) -> Any:
    """Slim each trajectory step for the judge's evidence block (safe drops)."""
    if not isinstance(trajectory, list):
        return trajectory
    return [_slim_evidence_value(step) for step in trajectory]


def _build_evidence_text(manifest: dict[str, Any], evidence: dict[str, Any]) -> str:
    cfg = (manifest.get("rubric") or {}).get("evidence") or {}
    # Per-batch/global override (stamped by harbor_composite.default_manifest);
    # falls back to the env/default cap when the key is absent (legacy tasks).
    try:
        max_chars = int(cfg.get("max_chars") or 0)
    except (TypeError, ValueError):
        max_chars = 0

    @srv.call_tool()
    async def _call_tool(
        tool_name: str, arguments: dict[str, Any] | None
    ) -> list[types.TextContent]:
        # HARBOR-LOCAL: reject calls outside the allowlist before any HTTP
        # work. Raising here surfaces a clear MCP error to the agent
        # ("tool 'x' is not allowed for this batch") instead of relying
        # on a 4xx from upstream that may or may not be routed cleanly.
        allowed = state.get("allowed_tools")
        if allowed is not None and tool_name not in allowed:
            raise RuntimeError(
                f"tool {tool_name!r} is not allowed for this batch"
            )
        headers = build_headers(state)
        async with httpx.AsyncClient(timeout=HTTP_TIMEOUT) as client:
            # HARBOR-LOCAL: pass the agent's call straight through to upstream.
            # We never substitute or "replay" golden-trajectory arguments — if a
            # call is missing a required argument, upstream returns its normal
            # error and the agent self-corrects. Injecting golden arguments here
            # would leak the reference solution into the run.
            resp = await do_step(
                client,
                state["upstream"],
                headers,
                {
                    "action_type": "ToolCallAction",
                    "tool_name": tool_name,
                    "arguments": arguments or {},
                },
            )
        obs = resp.get("observation") or {}
        if not obs.get("success"):
            raise RuntimeError(obs.get("error_message") or "upstream /step failed")
        result = obs.get("tool_result")
        payload = _extract_tool_payload(result)
        is_error = obs.get("is_error") or (
            isinstance(result, dict) and result.get("isError")
        )
        if is_error:
            # Surface the error message (Duplicate entry …, Validation failed …)
            # so the agent can correct course.
            raise RuntimeError(payload or "tool error")
        return [types.TextContent(type="text", text=payload)]

    return srv


async def health(_request: Request) -> JSONResponse:
    if READY:
        return JSONResponse(
            {"status": "ok", "servers": list(STATE.keys())}, status_code=200
        )
    return JSONResponse({"status": "starting"}, status_code=503)


def build_app() -> Starlette:
    mcp_servers = {name: build_mcp_server(name) for name in STATE}
    session_managers: dict[str, StreamableHTTPSessionManager] = {
        name: StreamableHTTPSessionManager(
            app=srv, event_store=None, json_response=False
        )
        for name, srv in mcp_servers.items()
    }

    def asgi_for(name: str):
        sm = session_managers[name]

        async def handler(scope, receive, send):
            await sm.handle_request(scope, receive, send)

        return handler

    @contextlib.asynccontextmanager
    async def lifespan(_app):
        async with contextlib.AsyncExitStack() as stack:
            for sm in session_managers.values():
                await stack.enter_async_context(sm.run())
            yield

    # Raw OpenEnv passthrough (used by the verifier to dump after-agent state,
    # and by solve.py in oracle mode to drive /reset + /step directly). Headers
    # are injected from STATE[name], identical to native-MCP side.
    async def raw_state(request: Request) -> JSONResponse:
        # HARBOR-LOCAL fix (see consistency/shortcut_audit.md and
        # environment/entrypoint.sh): this route runs arbitrary caller-supplied
        # SQL against the gym's backing database and is meant for the trusted
        # verifier only, never the agent. Gated behind a per-boot secret written
        # to a root-only path under /app, which the agent's own process cannot
        # read. Neither solve.py nor any allowlisted tool call ever needs this
        # route, so this cannot break legitimate grading or the oracle replay.
        expected = os.environ.get("RAW_STATE_SECRET", "")
        if not expected or request.headers.get("x-raw-state-secret") != expected:
            return JSONResponse({"error": "forbidden"}, status_code=403)
        name = request.path_params["name"]
        if name not in STATE:
            return JSONResponse({"error": f"unknown server {name}"}, status_code=404)
        s = STATE[name]
        qs = [v for k, v in request.query_params.multi_items() if k == "verify_queries"]
        async with httpx.AsyncClient(timeout=HTTP_TIMEOUT) as client:
            data = await do_state(client, s["upstream"], build_headers(s), qs)
        return JSONResponse(data)

    async def raw_step(request: Request) -> JSONResponse:
        name = request.path_params["name"]
        if name not in STATE:
            return JSONResponse({"error": f"unknown server {name}"}, status_code=404)
        s = STATE[name]
        # HARBOR-LOCAL fix (see consistency/shortcut_audit.md): enforce the same
        # allowed_tools check the normal MCP call path already applies in
        # _call_tool above, which this raw passthrough previously skipped
        # entirely -- letting a caller drive any tool the upstream mock API
        # exposes, not just the 14 tools this task allowlists. solve.py's own
        # oracle replay only ever names real allowlisted tools, so this does not
        # affect legitimate grading.
        body = await request.json()
        allowed = s.get("allowed_tools")
        tool_name = body.get("tool_name") if isinstance(body, dict) else None
        if allowed is not None and tool_name not in allowed:
            return JSONResponse(
                {"error": f"tool {tool_name!r} is not allowed for this batch"},
                status_code=403,
            )
        async with httpx.AsyncClient(timeout=HTTP_TIMEOUT) as client:
            data = await do_step(client, s["upstream"], build_headers(s), body)
        return JSONResponse(data)

    routes: list = [
        Route("/health", health, methods=["GET"]),
        Route("/raw/{name}/state", raw_state, methods=["GET"]),
        Route("/raw/{name}/step", raw_step, methods=["POST"]),
    ]
    for name in STATE:
        routes.append(Mount(f"/mcp/{name}", app=asgi_for(name)))

    return Starlette(routes=routes, lifespan=lifespan)


def main() -> None:
    try:
        asyncio.run(bootstrap())
    except SystemExit:
        raise
    except Exception as exc:
        die(f"bootstrap failed: {exc}")

    app = build_app()
    logger.info(
        "proxy listening on %s:%d — routes: %s",
        PROXY_HOST, PROXY_PORT, ["/health"] + [f"/mcp/{n}" for n in STATE],

            continue
        out.append(table)
    return sorted(out)


def _raw_state_secret() -> str:
    # HARBOR-LOCAL fix (see consistency/shortcut_audit.md): environment/
    # entrypoint.sh writes this to a root-only path under /app at container
    # boot; the verifier runs with the same /app access it already needs for
    # tests/ and solution/, so it can read this directly, while the agent
    # (rlgymagent, no access under /app) cannot.
    try:
        return Path("/app/.raw_state_secret").read_text().strip()
    except OSError:
        return ""


def query_state(server_name: str, query: str) -> list[dict[str, Any]]:
    base = f"{PROXY_BASE}/raw/{server_name}"
    headers = {"x-raw-state-secret": _raw_state_secret()}
    with httpx.Client(timeout=60.0) as c:
        r = c.get(f"{base}/state", params=[("verify_queries", query)], headers=headers)
        r.raise_for_status()
        body = r.json() or {}
    results = body.get("verification_results") or []
    if not results:
        return []
    return results[0].get("result") or []


def list_tables(server_name: str, state_cfg: dict[str, Any]) -> list[str]:
    rows = query_state(server_name, "SELECT name FROM sqlite_master WHERE type='table'")
    names = [str(r["name"]) for r in rows if r.get("name")]
    return selected_tables(names, state_cfg)


def table_meta(server_name: str, table: str, rows: list[dict[str, Any]]) -> dict[str, Any]:
    columns: list[str] = []
    primary_key: list[tuple[int, str]] = []
    column_types: dict[str, str] = {}
    try:
        info = query_state(server_name, f"PRAGMA table_info({quote_ident(table)})")
    except Exception as exc:  # noqa: BLE001
        print(f"[verifier] table_info failed for {server_name}.{table}: {exc}", file=sys.stderr)
        info = []
    for col in info:
        name = col.get("name")
        if name is not None:
            columns.append(str(name))
            column_types[str(name)] = str(col.get("type") or "")
        pk_index = int(col.get("pk") or 0)
        if pk_index > 0 and name is not None:
            primary_key.append((pk_index, str(name)))
    if not columns:
        columns = sorted({key for row in rows for key in row})
    return {
        "columns": columns,
        "primary_key": [name for _, name in sorted(primary_key)],
        "column_types": column_types,
    }

